  'سيصبح العقد «ملغي» وتتحول الوحدة إلى شاغرة. هل تريد المتابعة؟\n\nتنبيه: بعد الإلغاء تختفي معلومات هذا العقد ومستحقاته من التقارير. إذا كنت تحتاج الوحدة أو معلوماتها مستقبلًا فالأفضل «الأرشفة» بدل الإلغاء.': '合同将变为"已取消"，单元将变为空置。继续吗？\n\n注意：取消后，该合同及其应付款项将从报告中消失。如果将来需要该单元或其信息，归档比取消更合适。',
  'أُلغي العقد وأصبحت الوحدة شاغرة': '合同已取消，单元现为空置',
