  'الوحدة شاغرة ولا يوجد عقد لإلغائه': '单元空置；没有可取消的合同',
  'سيُلغى عقد الإيجار بعد عمل التسوية، ويصبح العقد «ملغي» والوحدة شاغرة. هل تريد المتابعة؟\n\nتنبيه: بعد الإلغاء تختفي معلومات هذا العقد ومستحقاته من التقارير. إذا كنت تحتاج الوحدة أو معلوماتها مستقبلًا فالأفضل «الأرشفة» بدل الإلغاء.': '结算后租约将被取消；合同变为"已取消"，单元变为空置。继续吗？\n\n注意：取消后，该合同及其应付款项将从报告中消失。如果将来需要该单元或其信息，归档比取消更合适。',
