  'إنه في يوم {تاريخ تحرير العقد} تم الاتفاق بين كلٍّ من الطرف الأول: {الطرف الأول}، والطرف الثاني: {الطرف الثاني}، وقد أقرّ الطرفان بأهليتهما للتعاقد واتفقا على ما يلي:': '于{تاريخ تحرير العقد}，甲方：{الطرف الأول}与乙方：{الطرف الثاني}达成协议。双方确认均具有缔约的法律行为能力，并约定如下：',
  'دفع المستأجر مبلغ تأمين قدره {مبلغ التأمين}، يُردّ إليه عند انتهاء العقد بعد خصم قيمة أي أضرار أو مستحقات قائمة.': '承租人已支付押金{مبلغ التأمين}，合同期满后扣除任何损坏赔偿或未结款项后予以退还。',
  'شروط إضافية: {شروط إضافية}': '附加条款：{شروط إضافية}',
  'حُرِّر هذا العقد من نسختين، بيد كل طرف نسخة للعمل بموجبها.': '本合同一式两份，双方各执一份，作为履行依据。',
  'مدة العقد من {تاريخ بداية العقد} إلى {تاريخ نهاية العقد}، ولا يُجدَّد إلا باتفاق مكتوب بين الطرفين.': '合同期限自{تاريخ بداية العقد}至{تاريخ نهاية العقد}，仅经双方书面同意方可续签。',
  'الأجرة السنوية {قيمة الإيجار السنوي}، تُدفع {طريقة الدفع} مقدمًا في مواعيد استحقاقها، ولا يحق للمستأجر تأخيرها أو الامتناع عنها.': '年租金为{قيمة الإيجار السنوي}，按{طريقة الدفع}于各到期日预先支付；承租人不得拖延或拒付。',
  'إذا تأخر المستأجر عن سداد الأجرة أو أخلّ بأي من التزاماته، يحق للمؤجر المطالبة بفسخ العقد وبما يستحقه وفق الأنظمة المعمول بها.': '如承租人逾期支付租金或违反任何义务，出租人有权依据适用法律要求解除合同并追讨应付款项。',
  'سبب الدين: {سبب الدين}.': '借款原因：{سبب الدين}。',
  'أتعهد بردّ المبلغ كاملًا إلى الدائن أو من يفوّضه في موعد أقصاه {تاريخ السداد}، وطريقة السداد: {طريقة السداد}.': '本人承诺最迟于{تاريخ السداد}前将全部款项归还债权人或其授权代表。还款方式：{طريقة السداد}。',
  'يُسدَّد المبلغ على {عدد الأقساط} أقساط، قيمة كل قسط {قيمة القسط}.': '该款项分{عدد الأقساط}期偿还，每期{قيمة القسط}。',
  'يُعدّ هذا الإيصال سندًا بالمبلغ، ويحق للدائن عند التأخر عن السداد المطالبة به بالطرق النظامية.': '本收据为该笔款项的凭证，如逾期未还，债权人有权通过法律途径追讨。',
  'وهذا إقرار مني بذلك وأنا بكامل أهليتي المعتبرة شرعًا ونظامًا.': '本人在具备完全法律行为能力的情况下作出此确认。',
  'يستعمل المستأجر العقار للغرض المتفق عليه ({الغرض من الإيجار}) فقط، ولا يحق له التأجير من الباطن أو التنازل عن العقد إلا بموافقة كتابية من المؤجر.': '承租人仅可将房产用于约定用途（{الغرض من الإيجار}），未经出租人书面同意，不得转租或转让合同。',
  'فواتير الخدمات (الكهرباء والماء والاتصالات) على {فواتير الخدمات على}، والصيانة البسيطة على {الصيانة البسيطة على}، والصيانة الأساسية والإنشائية على {الصيانة الأساسية على}.': '公用事业费用（电、水和通讯）由{فواتير الخدمات على}承担；小修由{الصيانة البسيطة على}承担；大修及结构性维修由{الصيانة الأساسية على}承担。',
  'لا يجوز للمستأجر إجراء أي تعديلات أو إنشاءات في العقار إلا بموافقة كتابية من المؤجر.': '未经出租人书面同意，承租人不得对房产进行任何改动或施工。',
  'يلتزم المستأجر بالمحافظة على العقار وتسليمه عند انتهاء العقد بالحالة التي استلمه بها، عدا الاستهلاك المعتاد.': '承租人应妥善维护房产，并于合同期满时按接收时的状态归还，正常损耗除外。',
  'منح المؤجر المستأجر فترة سماح للتجهيز مدتها {فترة السماح للتجهيز} لا تُحتسب فيها أجرة.': '出租人给予承租人{فترة السماح للتجهيز}的装修免租期，期间不收取租金。',
  'يستعمل المستأجر المحل لممارسة نشاط ({نوع النشاط}) تحت الاسم التجاري ({الاسم التجاري}) فقط، ولا يحق له تغيير النشاط أو التأجير من الباطن إلا بموافقة كتابية من المؤجر.': '承租人仅可以商号（{الاسم التجاري}）将商铺用于（{نوع النشاط}）经营活动，未经出租人书面同意，不得变更经营活动或转租。',
  'يلتزم المستأجر باستخراج التراخيص اللازمة لنشاطه وتجديدها قبل انتهائها، ويتحمّل وحده أي مخالفات أو غرامات تنشأ عن نشاطه.': '承租人应办理经营所需的执照并在到期前续期，并独自承担因其经营活动产生的任何违规及罚款。',
  'فواتير الخدمات على {فواتير الخدمات على}، والصيانة على {الصيانة على}، واللوحات والديكور على {اللوحات والديكور على}.': '公用事业费用由{فواتير الخدمات على}承担；维修由{الصيانة على}承担；招牌和装饰由{اللوحات والديكور على}承担。',
  'عند انتهاء العقد يسلّم المستأجر المحل خاليًا من الشواغل وبالحالة التي استلمه بها، وتؤول التحسينات الثابتة للمؤجر ما لم يُتفق على غير ذلك.': '合同期满时，承租人应将商铺腾空并按接收时的状态归还；除另有约定外，固定改良设施归出租人所有。',
  'مدة الإيجار من {تاريخ بداية العقد} إلى {تاريخ نهاية العقد}، وأجرة المركبة {قيمة الإيجار} على أساس {أساس التأجير}.': '租期自{تاريخ بداية العقد}至{تاريخ نهاية العقد}，车辆租金为{قيمة الإيجار}，按{أساس التأجير}计费。',
  'دفع المستأجر مبلغ تأمين قدره {مبلغ التأمين}، يُردّ عند إعادة المركبة سليمة بعد خصم أي مستحقات.': '承租人已支付押金{مبلغ التأمين}，车辆完好归还并扣除任何应付款项后予以退还。',
  'استلم المستأجر المركبة بحالة جيدة، وقراءة العداد {قراءة العداد عند التسليم} كم، ومستوى الوقود {مستوى الوقود عند التسليم}، ويعيدها بالحالة نفسها.': '承租人已接收车况良好的车辆，里程表读数为{قراءة العداد عند التسليم}公里，油量为{مستوى الوقود عند التسليم}，并应按原状归还。',
  'الكيلومترات المسموحة {الكيلومترات المسموحة} كم، وما زاد عليها يُحتسب بواقع {رسوم الكيلومتر الإضافي} لكل كيلومتر.': '允许行驶里程为{الكيلومترات المسموحة}公里，超出部分按每公里{رسوم الكيلومتر الإضافي}收费。',
  'المستأجر مسؤول عن المخالفات المرورية والحوادث وما يترتب عليها طوال مدة الإيجار، وعليه إبلاغ المؤجر والجهات المختصة فور وقوع أي حادث.': '租赁期间，承租人对交通违章、事故及其后果负责，发生任何事故时须立即通知出租人及有关部门。',
  'لا يحق للمستأجر السماح لغيره بقيادة المركبة، أو استعمالها في غير الغرض المعتاد، أو الخروج بها خارج الدولة إلا بموافقة كتابية من المؤجر.': '未经出租人书面同意，承租人不得允许他人驾驶车辆、将车辆用于非正常用途或驶出国境。',
  'الوقود على {الوقود على}، والصيانة الدورية على {الصيانة الدورية على}، ونوع التأمين على المركبة: {التأمين على المركبة}.': '燃油由{الوقود على}承担；定期保养由{الصيانة الدورية على}承担；车辆保险类型：{التأمين على المركبة}。',
  'التأخر في إعادة المركبة عن الموعد المحدد يُحتسب بأجرة يوم كامل عن كل يوم تأخير أو جزء منه.': '逾期还车的，每逾期一天或不足一天均按全天租金计费。',
  'موضوع العقد: {موضوع العقد}': '合同标的：{موضوع العقد}',
  'قيمة العقد {قيمة العقد}، تُدفع {طريقة الدفع}.': '合同金额为{قيمة العقد}，按{طريقة الدفع}支付。',
  'مدة العقد من {تاريخ بداية العقد} إلى {تاريخ نهاية العقد}.': '合同期限自{تاريخ بداية العقد}至{تاريخ نهاية العقد}。',
  'يلتزم الطرف الأول بما يلي: {التزامات الطرف الأول}': '甲方承诺履行以下义务：{التزامات الطرف الأول}',
  'يلتزم الطرف الثاني بما يلي: {التزامات الطرف الثاني}': '乙方承诺履行以下义务：{التزامات الطرف الثاني}',
  'في حال إخلال أي طرف بالتزاماته يحق للطرف الآخر المطالبة بالتعويض وفسخ العقد وفق الأنظمة المعمول بها.': '任何一方违反其义务的，另一方有权依据适用法律要求赔偿并解除合同。',
