  'آخر تحديث: 12 أكتوبر 2026': '最后更新：2026年10月12日',
  'توضح هذه السياسة كيف يجمع تطبيق Fundly بياناتك ويستخدمها ويحميها، وحقوقك عليها. باستخدامك التطبيق فأنت توافق على ما ورد فيها.': '本政策说明 Fundly 应用如何收集、使用和保护您的数据，以及您对这些数据享有的权利。使用本应用即表示您同意本政策所载内容。',
  'من نحن ونطاق السياسة': '关于我们及本政策的适用范围',
  'تطبيق Fundly («التطبيق»، «نحن») لإدارة الأموال والالتزامات والأصول والعلاقات. تسري هذه السياسة على كل ما يُجمع أو يُعالَج عبر التطبيق وخدماته، وتُطبَّق وفق نظام حماية البيانات الشخصية في المملكة العربية السعودية ولائحته التنفيذية، وأنظمة حماية البيانات المعمول بها في بلد المستخدم بالقدر الذي ينطبق عليه.': 'Fundly（“本应用”或“我们”）是一款用于管理资金、义务、资产和关系的应用。本政策适用于通过本应用及其服务收集或处理的所有数据，并依据沙特阿拉伯王国《个人数据保护法》（PDPL）及其实施条例，以及在适用范围内用户所在国家现行的数据保护法律予以执行。',
  'البيانات التي نجمعها': '我们收集的数据',
  '• بيانات الحساب: الاسم، ورقم الهاتف أو البريد الإلكتروني المستخدم في الدخول، والرقم التعريفي الذي يُنشئه التطبيق لك.\n• البيانات التي تدخلها بنفسك: الالتزامات والمصروفات والدخل والديون والعهد والأقساط، وبيانات العقارات والأنشطة والمركبات وعقود الإيجار والدفعات، والمستندات والمرفقات والنماذج والتقارير.\n• بيانات أشخاص آخرين تسجّلها أنت: مثل المستأجرين والمؤجرين والأفراد والجهات وأرقام هوياتهم وهواتفهم.\n• الموقع الجغرافي: عند ضغطك زر جلب الموقع فقط، وبعد إذنك.\n• بيانات تقنية محدودة يلزمها التشغيل، مثل سجلات الاتصال لدى مزوّد الاستضافة لأغراض الأمان.\nلا نستخدم أدوات إعلانات أو تتبّع أو تحليلات سلوكية من أطراف ثالثة.': '• 账户数据：姓名、用于登录的手机号码或电子邮箱，以及本应用为您生成的识别号。\n• 您自行录入的数据：义务、支出、收入、债务、保管款项和分期付款；房产、经营活动、车辆、租赁合同和付款数据；以及文件、附件、模板和报告。\n• 您记录的他人数据：如承租人、出租人、个人和机构，及其身份证件号码和电话号码。\n• 地理位置：仅在您点击“获取位置”按钮时，并经您授权后收集。\n• 运行所需的有限技术数据，例如托管服务提供商出于安全目的保存的连接日志。\n我们不使用任何第三方广告、跟踪或行为分析工具。',
  'لماذا نعالج بياناتك': '我们处理您数据的目的',
  '• تقديم خدمات التطبيق وحفظ سجلاتك ومزامنتها بين أجهزتك.\n• إنشاء التذكيرات والتنبيهات والتقارير التي تطلبها.\n• تنفيذ المشاركة التي تختارها مع مستخدمين آخرين (العهد والديون والالتزامات المشتركة والتفويضات).\n• الرد على طلبات الدعم.\n• حماية الحسابات ومنع الاستخدام غير المشروع والالتزام بالأنظمة.\nنعالج البيانات لتنفيذ الخدمة التي طلبتها، وبموافقتك فيما يحتاج موافقة (الموقع والكاميرا والصور)، وللوفاء بالتزاماتنا النظامية. ولا نستخدمها لأي غرض آخر دون إبلاغك.': '• 提供本应用的服务，保存您的记录并在您的设备之间同步。\n• 生成您所要求的提醒、通知和报告。\n• 执行您选择与其他用户进行的共享（保管款项、债务、共同义务和授权）。\n• 答复支持请求。\n• 保护账户安全，防止非法使用，并遵守相关法律法规。\n我们处理数据是为了履行您所请求的服务；对于需要同意的事项（位置、相机和照片），基于您的同意进行处理；以及为履行我们的法定义务。未经告知，我们不会将数据用于任何其他目的。',
  'أين تُحفظ بياناتك': '您的数据存储位置',
  '• السجلات الأساسية والمرفقات المرفوعة تُحفظ لدى مزوّد الاستضافة السحابية (Supabase)، مقيّدة بحسابك بضوابط وصول على مستوى السجل، فلا يطّلع عليها حساب آخر إلا ما تشاركه أنت.\n• تُحفظ على جهازك فقط: التفضيلات، وصورة الملف الشخصي، ورمز قفل التطبيق، والتوقيع والختم والشعار، ودليل الأفراد والجهات، والمستندات العامة، والتذكيرات المحلية. حذف التطبيق يحذف هذه البيانات من الجهاز.\n• قد تُعالَج البيانات على خوادم خارج بلدك، ونلتزم عندئذ بالضمانات التي تشترطها الأنظمة لنقل البيانات خارج الحدود.': '• 核心记录和上传的附件存储于云托管服务提供商（Supabase），并通过记录级访问控制限定于您的账户，除您主动共享的内容外，其他账户均无法查看。\n• 仅存储在您设备上的数据：偏好设置、个人头像、应用锁密码、签名、印章和标志、个人与机构通讯录、通用文件以及本地提醒。删除本应用将从设备中删除这些数据。\n• 数据可能在您所在国家以外的服务器上处理；在此情况下，我们将遵守法律对数据跨境传输所要求的保障措施。',
  'مشاركة البيانات والإفصاح عنها': '数据共享与披露',
  '• لا نبيع بياناتك ولا نؤجّرها ولا نشاركها لأغراض تسويقية.\n• المشاركة داخل التطبيق تتم بطلبك: عند إسناد عهدة أو دين أو إضافة عضو بالرقم التعريفي يرى الطرف الآخر العنصر المشترك واسمك فقط، ولا يُكشف هاتفك أو عنوانك إلا بموافقتك.\n• ما تشاركه عبر زر المشاركة أو الطباعة (PDF أو صورة) يخرج بإرادتك وعبر التطبيق الذي تختاره.\n• نستعين بمزوّدي خدمة (الاستضافة والتخزين) يعالجون البيانات نيابةً عنّا وفق التزامات تعاقدية بالسرية والأمان.\n• قد نفصح عن البيانات إذا ألزمنا بذلك نظام أو أمر قضائي أو جهة مختصة.': '• 我们不会出售或出租您的数据，也不会出于营销目的共享您的数据。\n• 应用内的共享依您的请求进行：当您分配保管款项或债务，或通过识别号添加成员时，对方仅能看到共享项目和您的姓名；未经您同意，不会披露您的电话号码或地址。\n• 您通过分享或打印按钮（PDF 或图片）分享的内容，系出于您的意愿并通过您选择的应用传出。\n• 我们委托服务提供商（托管和存储）代表我们处理数据，并要求其承担保密和安全方面的合同义务。\n• 如法律、法院命令或主管机关要求，我们可能会披露数据。',
  '• الكاميرا والصور والملفات: لإرفاق المستندات والصور والختم والشعار وصورة الملف الشخصي.\n• الموقع: لتعبئة حقل الموقع عند طلبك فقط.\n• الإنترنت: لمزامنة بياناتك.\nيمكنك سحب أي إذن من إعدادات جهازك في أي وقت، وتبقى بقية خصائص التطبيق تعمل.': '• 相机、照片和文件：用于附加文件、图片、印章、标志和个人头像。\n• 位置：仅在您请求时用于填写位置字段。\n• 互联网：用于同步您的数据。\n您可随时在设备设置中撤回任何权限，本应用的其他功能仍可正常使用。',
  'الاحتفاظ بالبيانات': '数据保留',
  'نحتفظ ببياناتك ما دام حسابك قائمًا. ما تحذفه ينتقل إلى سلة المهملات حتى تحذفه نهائيًا. وعند حذف الحساب تُحذف بياناته من أنظمتنا خلال مدة لا تتجاوز 30 يومًا، عدا ما يلزم الاحتفاظ به نظامًا، وتُزال من النسخ الاحتياطية وفق دورتها.': '只要您的账户存续，我们即保留您的数据。您删除的内容将移至回收站，直至您将其永久删除。账户删除后，其数据将在不超过 30 天的期限内从我们的系统中删除（依法须保留的数据除外），并按备份轮换周期从备份中清除。',
  'أمن البيانات': '数据安全',
  '• تشفير الاتصال بين التطبيق والخوادم (TLS).\n• ضوابط وصول تقصر كل سجل على صاحبه ومن يشاركه.\n• قفل التطبيق برمز، وخيار إخفاء المبالغ.\nلا توجد وسيلة نقل أو تخزين آمنة تمامًا، لذا نوصيك بحماية جهازك وعدم مشاركة رمز القفل.': '• 对本应用与服务器之间的连接进行加密（TLS）。\n• 访问控制，将每条记录限定于其所有者及其共享对象。\n• 应用密码锁，以及隐藏金额选项。\n任何传输或存储方式都无法做到绝对安全，因此我们建议您保护好自己的设备，切勿共享锁定密码。',
  'حقوقك': '您的权利',
  'وفق الأنظمة المعمول بها لك الحق في:\n• العلم بكيفية جمع بياناتك ومعالجتها.\n• الوصول إلى بياناتك والحصول على نسخة منها.\n• تصحيحها أو تحديثها.\n• طلب حذفها أو إتلافها.\n• الرجوع عن موافقتك فيما بُني عليها.\n• تقديم شكوى إلى الجهة المختصة بحماية البيانات في بلدك (في المملكة العربية السعودية: الهيئة السعودية للبيانات والذكاء الاصطناعي «سدايا»).\nنرد على طلبك خلال 30 يومًا من استلامه.': '根据适用法律，您有权：\n• 了解您的数据如何被收集和处理。\n• 访问您的数据并获取其副本。\n• 更正或更新您的数据。\n• 要求删除或销毁您的数据。\n• 对基于您同意而进行的处理撤回同意。\n• 向您所在国家的数据保护主管机关投诉（在沙特阿拉伯王国：沙特数据和人工智能管理局（SDAIA））。\n我们将在收到您的请求后 30 天内予以答复。',
  'حذف الحساب': '删除账户',
  'يمكنك حذف أي سجل من داخل شاشته في أي وقت. ولحذف حسابك وكل بياناته استخدم زر «طلب حذف الحساب» أسفل هذه الصفحة، أو راسلنا على بريد الدعم من البريد أو الرقم المرتبط بحسابك، وسنتحقق من الطلب وننفّذه.': '您可随时在相应页面中删除任何记录。如需删除您的账户及其全部数据，请使用本页底部的“申请删除账户”按钮，或使用与您账户关联的邮箱或号码发送邮件至支持邮箱；我们将核实请求并予以执行。',
  'بيانات الآخرين التي تدخلها': '您录入的他人数据',
  'عند تسجيلك بيانات أشخاص آخرين (كالمستأجرين أو الأفراد أو أطراف العقود) فأنت مسؤول عن أن يكون لديك أساس نظامي لذلك، وأن تستخدمها لأغراضك المشروعة فقط.': '当您录入他人数据（如承租人、个人或合同当事方）时，您有责任确保具备相应的合法依据，并仅将其用于您的正当目的。',
  'الاشتراكات والمدفوعات': '订阅与付款',
  'عند تفعيل الاشتراكات المدفوعة تتم عمليات الدفع عبر متاجر التطبيقات أو بوابات دفع مرخّصة، ولا نحفظ بيانات بطاقتك.': '启用付费订阅后，付款将通过应用商店或持牌支付网关完成，我们不会存储您的银行卡信息。',
  'الأطفال': '儿童',
  'التطبيق موجّه لمن بلغ 18 عامًا، ولا نجمع عن قصد بيانات من هم دون ذلك.': '本应用面向年满 18 周岁的人士，我们不会在知情的情况下收集未满该年龄者的数据。',
  'التعديلات على السياسة': '本政策的变更',
  'قد نحدّث هذه السياسة، ونُبلغك داخل التطبيق بأي تغيير جوهري قبل سريانه. واستمرارك في الاستخدام بعد السريان يعني موافقتك على النسخة المحدّثة.': '我们可能会更新本政策，并在任何重大变更生效前通过本应用通知您。变更生效后您继续使用本应用，即表示您同意更新后的版本。',
  'التواصل معنا': '联系我们',
  'لأي سؤال أو طلب يتعلق بخصوصيتك راسلنا على بريد الدعم: support@fundly.app': '如对您的隐私有任何疑问或请求，请发送邮件至我们的支持邮箱：support@fundly.app',
  'طلب حذف الحساب': '申请删除账户',
  'سيُفتح بريدك برسالة جاهزة لطلب حذف حسابك وكل بياناته نهائيًا. أرسلها من البريد أو الرقم المرتبط بحسابك. هل تريد المتابعة؟': '将打开您的邮件应用，并附有一封已拟好的邮件，用于申请永久删除您的账户及其全部数据。请使用与您账户关联的邮箱或号码发送。是否继续？',
  'تعذّر فتح البريد — نُسخ بريد الدعم لتراسلنا منه': '无法打开邮件应用——已复制支持邮箱地址，方便您与我们联系',
  'بياناتك وحقوقك وطلب حذف الحساب': '您的数据、权利及账户删除申请',
