  'اسحب التوقيع والختم إلى مكانهما ثم اضغط «حفظ».': '将签名和印章拖到位置，然后点击“保存”。',
  'إرفاق الملف': '附加文件',
  'أرفق الملف أولًا': '请先附加文件',
  'ملف جديد': '新文件',
  'حُفظت نسخة موقّعة': '已保存签名副本',
  'يوجد تنبيه': '有提醒',
  'موقّع': '已签名',
  'الصفحة': '页',
  'اعتماد المصروفات': '费用审批',
  'بموافقة صاحب العهدة': '需保管款所有人批准',
  'بدون موافقة': '无需批准',
  'حالة الاعتماد': '审批状态',
  'بانتظار الاعتماد': '待审批',
  'يحتاج المصروف موافقة صاحب العهدة لاعتماده': '费用需保管款所有人批准',
  'كل مصروف يرسله المستلم يصلك لتعتمده أو ترفضه، ولا يُخصم من العهدة قبل اعتماده.': '接收人提交的每笔费用都会发送给您批准或拒绝，批准前不会从保管款中扣除。',
  'مصروفات المستلم تُخصم من العهدة مباشرة بلا موافقة.': '接收人的费用将直接从保管款中扣除，无需批准。',
  'العهدة مسندة — الصرف عند الطرف الآخر، وكل مصروف يرسله يصلك هنا لتعتمده أو ترفضه.': '保管款已指派 — 由对方支出，对方提交的每笔费用都会发送到这里供您批准或拒绝。',
  'اعتماد': '批准',
  'اعتُمد المصروف وخُصم من العهدة': '费用已批准并从保管款中扣除',
  'رُفض المصروف ولم يُخصم من العهدة': '费用已拒绝，未从保管款中扣除',
  'أُرسل المصروف لاعتماد صاحب العهدة': '费用已提交保管款所有人审批',
  'تم حفظ عهدة مالية جديدة': '已保存新的保管款',
  'إلغاء العهدة': '取消保管款',
  'أُلغيت العهدة — يمكنك حذفها الآن من القائمة ⋮': '保管款已取消 — 现在可从 ⋮ 菜单中删除',
  'تسوية العهدة': '结清保管款',
  'ستُغلق العهدة نهائيًا ولا يُصرف منها بعد ذلك.': '保管款将被永久关闭，此后不能再支出。',
  'تاريخ التسوية': '结清日期',
  'المبلغ المعاد عند التسوية': '结清时退回金额',
  'تمت تسوية العهدة': '保管款已结清',
  'إضافة مبلغ على العهدة': '向保管款追加金额',
  'سجل العهدة والصرفيات': '保管款记录与支出',
  'إزالة من المثبتة': '从固定项中移除',
  'سيُزال من هنا فقط ولن يُحذف من التطبيق، ويمكنك تثبيته مرة أخرى بزر +.': '仅从此处移除，不会从应用中删除。可通过 + 按钮重新固定。',
  'مصروفات بانتظار الاعتماد': '待审批费用',
  'اعتمدها أو ارفضها قبل التسوية.': '请在结清前批准或拒绝。',
  'من الاستديو': '从相册',
  'حفظ الملاحظة': '保存笔记',
  'اسم الملاحظة': '笔记名称',
  'اختر التاريخ للتذكير': '请选择提醒日期',
  'الخروج بدون حفظ؟': '不保存就离开？',
  'لن تُحفظ التغييرات على هذه الملاحظة. لحفظها اضغط «تم».': '此笔记的更改不会保存。要保存，请点击“完成”。',
  'خروج': '离开',
  'متابعة الكتابة': '继续编辑',
  'صف': '行',
  'عمود': '列',
  'حذف الجدول': '删除表格',
  'ملاحظة جديدة': '新笔记',
  'خط كبير': '大号文字',
  'إخفاء الكيبورد': '隐藏键盘',
