  '، ثم يعود حسابك إلى الباقة الأساسية وتبقى بياناتك محفوظة. لا تُسترد المبالغ المدفوعة عن المدة الحالية.': '，之后您的账户将恢复为基础套餐，数据会保留。当前周期已付款项不予退还。',
  'آخر تحديث: 17 أكتوبر 2026': '最后更新：2026年10月17日',
