  'اختيار من التقويم': '从日历选择',
  'اكتب «تاريخ الميلاد» في تعديل الملف الشخصي — والباقي يحسبه التطبيق لك.': '在“编辑个人资料”中填写出生日期，其余由应用为您计算。',
  'الأسعار المعروضة نهائية وتشمل ضريبة القيمة المضافة حيث تنطبق، ولا يضيف التطبيق أي رسوم أخرى. قد يطبّق البنك أو المتجر رسوم تحويل العملة.': '显示价格为最终价格，并在适用时含增值税；应用不收取其他费用。银行或商店可能收取货币兑换费。',
  'الأهلية والحساب': '资格与账户',
  'الاستخدام المقبول': '可接受的使用',
  'الاسترداد': '退款',
  'الاشتراك الشهري أو السنوي يتجدد تلقائيًا في نهاية كل مدة بنفس السعر حتى تلغي التجديد. الهدية لا تتجدد وتنتهي بنهاية مدتها.': '月度或年度订阅在每个周期结束时按相同价格自动续订，直至您取消续订。礼物不会续订，到期即结束。',
  'الاشتراك المُهدى يبدأ يوم تفعيل كوده من المُهدى إليه، وينتهي بنهاية مدته دون تجديد. لا تُسترد قيمة الهدية بعد شرائها أو تفعيلها، ولا تُستبدل نقدًا.': '礼物订阅自受赠人兑换代码之日开始，到期结束且不续订。礼物一经购买或兑换不予退款，也不可兑换现金。',
  'التجديد التلقائي': '自动续订',
  'التطبيق أداة لتنظيم وتسجيل الأموال والالتزامات والأصول والعلاقات. ما يعرضه من أرقام وتنبيهات وتقارير مبني على ما تدخله أنت، ولا يُعد استشارة مالية أو قانونية أو محاسبية أو ضريبية.': '本应用是整理和记录资金、承诺、资产和关系的工具。其数字、提醒和报告基于您输入的内容，不构成财务、法律、会计或税务建议。',
  'التعديلات على الشروط': '条款变更',
  'التواصل بشأن المدفوعات': '付款咨询',
  'التوفر والتعديلات على الخدمة': '服务可用性与变更',
  'الدفع داخل التطبيق لم يُفعَّل بعد، فتُفعَّل الباقة الآن تجريبيًا بلا أي خصم. يبدأ الاشتراك فورًا ويتجدد تلقائيًا في نهاية المدة حتى تلغي التجديد، وتتغير صلاحيات الأقسام فورًا.': '应用内支付尚未开通，因此套餐现以试用方式免费启用。订阅立即开始，并在周期结束时自动续订，直至您取消续订；各模块权限立即变更。',
  'الرسوم والضرائب': '费用与税费',
  'المشاركة مع مستخدمين آخرين': '与其他用户共享',
  'النظام الواجب التطبيق': '适用法律',
  'بدأ في': '开始于',
  'بعد الإلغاء': '取消后',
  'بنفس السعر والمدة.': '价格和周期不变。',
  'بياناتك ومحتواك': '您的数据与内容',
  'تاريخ الميلاد غير صحيح — اكتبه يوم/شهر/سنة مثل 17/9/1984': '出生日期无效 — 请按 日/月/年 填写，如 17/9/1984',
  'تخضع هذه الشروط لأنظمة المملكة العربية السعودية، وتختص محاكمها بالنظر في أي نزاع ينشأ عنها، دون إخلال بحقوقك النظامية في بلد إقامتك.': '本条款受沙特阿拉伯王国法律管辖，由其法院处理由此产生的任何争议，但不影响您在居住国的法定权利。',
  'تنبيه: عند إلغاء الاشتراك أو الهدية لا تُسترد المبالغ المدفوعة، ويبقى الاشتراك فعّالًا حتى نهاية مدته.': '注意：取消订阅或礼物不退还已付款项，订阅在周期结束前保持有效。',
  'تنظّم هذه الشروط استخدامك تطبيق Fundly وخدماته. باستخدامك التطبيق فأنت توافق عليها وعلى سياسة الخصوصية، فإن لم توافق فتوقف عن الاستخدام.': '本条款规范您对 Fundly 应用及其服务的使用。使用本应用即表示您同意本条款及隐私政策；如不同意，请停止使用。',
  'تواصل بشأن المدفوعات': '就付款联系我们',
  'تُقدَّم الخدمة «كما هي». وبالقدر الذي تسمح به الأنظمة لا نتحمل المسؤولية عن أي خسارة غير مباشرة، أو عن قرارات اتخذتها بناءً على بيانات أدخلتها، أو عن فقد بيانات محفوظة على جهازك فقط.': '本服务按“现状”提供。在法律允许的范围内，我们不对任何间接损失、您基于所输入数据做出的决定，或仅存储在您设备上的数据丢失承担责任。',
  'حدود المسؤولية': '责任限制',
  'سيتجدد اشتراكك تلقائيًا في': '您的订阅将自动续订于',
  'شروط الاستخدام': '使用条款',
  'شروط الاشتراك والدفع': '订阅与付款条款',
  'شروط الخدمة والاشتراكات والمدفوعات': '服务、订阅与付款条款',
  'طبيعة الخدمة': '服务性质',
  'عند إسناد عهدة أو ربط دين أو إضافة أعضاء إلى التزام مشترك، يرى الطرف الآخر العنصر المشترك وما يسجّله فيه. كل طرف مسؤول عمّا يسجّله أو يعتمده، والتطبيق وسيلة توثيق ولا يضمن وفاء أي طرف بالتزاماته تجاه الآخر.': '当您分配保管、关联债务或向共享承诺添加成员时，对方可以看到共享项目及其中的记录。各方对自己记录或批准的内容负责；本应用仅用于记录，不保证任何一方履行对另一方的义务。',
  'قد نحدّث هذه الشروط، ونُبلغك داخل التطبيق بأي تغيير جوهري قبل سريانه. واستمرارك في الاستخدام بعد السريان يعني موافقتك على النسخة المحدّثة.': '我们可能更新本条款，并会在重大变更生效前于应用内通知您。之后继续使用即表示您接受更新后的版本。',
  'لأي استفسار عن الدفع أو الفواتير أو الاسترداد راسلنا من «تواصل معنا» على بريد الدعم، مع تاريخ العملية ورقم الإصدار.': '如对付款、发票或退款有任何疑问，请通过“联系我们”发送邮件至支持邮箱，并注明交易日期和版本号。',
  'لأي سؤال عن هذه الشروط أو عن الاشتراكات والمدفوعات راسلنا على بريد الدعم: support@fundly.app': '如对本条款或订阅与付款有任何疑问，请发送邮件至：support@fundly.app',
  'لا تُسترد المبالغ المدفوعة عن مدة بدأت، ولا قيمة الهدية بعد شرائها أو تفعيلها، إلا ما يوجبه النظام أو سياسة المتجر الذي تمت منه عملية الدفع.': '已开始周期的款项及已购买或兑换的礼物均不予退款，法律或付款所用商店政策另有规定的除外。',
  'لا يُقطع الاشتراك فورًا: يبقى فعّالًا حتى نهاية المدة المدفوعة، ثم يعود حسابك إلى الباقة الأساسية وتبقى كل بياناتك محفوظة.': '订阅不会立即终止：在已付周期结束前保持有效，之后账户恢复为基础套餐，所有数据都会保留。',
  'متى يبدأ الاشتراك': '订阅何时开始',
  'مفعّل': '已开启',
  'ملغى — يبقى فعّالًا حتى نهاية المدة': '已取消 — 有效期至周期结束',
  'من هذه الصفحة بزر «إلغاء التجديد التلقائي»، أو من إدارة الاشتراكات في متجر التطبيقات الذي دفعت منه، قبل موعد التجديد بيوم على الأقل.': '在本页点击“取消自动续订”，或在您付款所用应用商店的订阅管理中操作，至少在续订日前一天。',
  'نعمل على أن تكون الخدمة متاحة باستمرار، لكن قد تتوقف مؤقتًا للصيانة أو لأسباب خارجة عن إرادتنا. وقد نطوّر الميزات أو نعدّلها، ونُبلغك داخل التطبيق بأي تغيير جوهري يمس اشتراكك.': '我们力求服务持续可用，但可能因维护或不可控原因暂时中断。我们可能开发或调整功能，并会在应用内通知影响您订阅的重大变更。',
  'هدية — لا تتجدد': '礼物 — 不续订',
  'يبدأ فور تأكيد الدفع وتُحسب مدته من يوم الدفع. والهدية تبدأ يوم تفعيل كودها من المُهدى إليه، لا يوم شرائها.': '付款确认后立即开始，周期自付款日起计算。礼物自受赠人兑换代码之日开始，而非购买之日。',
  'يبقى اشتراكك فعّالًا حتى': '您的订阅有效期至',
  'يتجدد تلقائيًا في': '自动续订于',
  'يتجدد في': '续订于',
  'يمكنك حذف حسابك في أي وقت من الإعدادات. ويحق لنا تعليق الحساب أو إيقافه عند مخالفة هذه الشروط، مع إبلاغك بالسبب ما لم يمنع ذلك نظام.': '您可随时在设置中删除账户。若违反本条款，我们可暂停或终止账户，并告知原因，法律禁止的除外。',
  'يوم/شهر/سنة — مثل 17/9/1984': '日/月/年 — 如 17/9/1984',
  'يُمنع استخدام التطبيق في أي نشاط مخالف للأنظمة أو في الاحتيال أو انتحال الشخصية، أو محاولة الوصول إلى حسابات أو بيانات غيرك، أو تعطيل الخدمة، أو نسخ التطبيق أو تفكيكه أو إعادة بيعه.': '禁止将本应用用于任何违法活动、欺诈或冒充他人，禁止试图访问他人账户或数据、干扰服务，或复制、反向工程或转售本应用。',
  '• التطبيق لمن بلغ 18 عامًا.\n• أنت مسؤول عن صحة بيانات حسابك، وعن سرية كلمة المرور ورمز قفل التطبيق، وعن كل ما يتم من حسابك.\n• أبلغنا فورًا إن اشتبهت في استخدام حسابك دون إذنك.': '• 本应用面向年满18岁的用户。\n• 您对账户数据的准确性、密码和应用锁密码的保密以及通过您账户进行的一切操作负责。\n• 如怀疑账户被未经授权使用，请立即告知我们。',
  '• ما تدخله من بيانات ومستندات يبقى ملكك، وتمنحنا حق معالجته بالقدر اللازم لتقديم الخدمة فقط وفق سياسة الخصوصية.\n• أنت مسؤول عن مشروعية ما تسجّله من بيانات أشخاص آخرين وعن حصولك على ما يلزم لذلك.': '• 您输入的数据和文件仍归您所有；您仅授权我们按隐私政策在提供服务所需范围内处理。\n• 您对所记录他人数据的合法性及取得必要授权负责。',
  '• يبدأ الاشتراك فور تأكيد الدفع وتُحسب مدته من يوم الدفع.\n• يتجدد الاشتراك الشهري أو السنوي تلقائيًا بنفس السعر حتى تلغي التجديد من صفحة الاشتراكات أو من متجر التطبيقات قبل موعد التجديد بيوم على الأقل.\n• إلغاء التجديد لا يقطع الاشتراك فورًا: يبقى فعّالًا حتى نهاية المدة المدفوعة ثم يعود الحساب إلى الباقة الأساسية وتبقى البيانات محفوظة.\n• لا تُسترد المبالغ المدفوعة عن مدة بدأت، إلا ما يوجبه النظام أو سياسة المتجر الذي تمت منه عملية الدفع.\n• الأسعار المعروضة نهائية وتشمل ضريبة القيمة المضافة حيث تنطبق، وقد يطبّق البنك أو المتجر رسوم تحويل العملة.': '• 订阅在付款确认后立即开始，周期自付款日起计算。\n• 月度或年度订阅按相同价格自动续订，直至您在续订日前至少一天通过订阅页面或应用商店取消续订。\n• 取消续订不会立即终止订阅：在已付周期结束前保持有效，之后账户恢复为基础套餐，数据会保留。\n• 已开始周期的款项不予退款，法律或付款所用商店政策另有规定的除外。\n• 显示价格为最终价格，并在适用时含增值税；银行或商店可能收取货币兑换费。',
  'أضف شعارك من «المزيد» ← «التوقيع الإلكتروني والختم» ليظهر أعلى كل نموذج': '从“更多”→“电子签名与印章”添加您的徽标，使其显示在每个模板顶部',
  'أُضيف إلى الأفراد والجهات، ويمكنك من هناك إضافة أي بيانات أخرى عنه': '已添加到“个人与机构”，您可以在那里补充其他信息',
