  'ستُغلق العهدة ولا يُصرف منها بعد ذلك. اكتب ما تم في التسوية (مثل: استلمت المتبقي نقدًا)، ثم اختر إبقاءها أو أرشفتها.': '保管将被关闭，之后不能再支出。请填写结算情况（如：已收回剩余现金），然后选择保留或归档。',
